import 'package:flutter/foundation.dart';
import '../database/db_helper.dart'; import '../models/cart_item.dart'; import '../models/product.dart';
class ProductProvider extends ChangeNotifier { final _db=DBHelper.instance; List<Product> products=[]; bool loading=true; ProductProvider(){loadProducts();} Future<void> loadProducts() async {products=await _db.getProducts(); if(products.isEmpty){for(final p in dummyProducts){await _db.insertProduct(p);} products=await _db.getProducts();} loading=false; notifyListeners();} Future<void> addProduct(Product p) async {await _db.insertProduct(p);products=await _db.getProducts();notifyListeners();} }
class CartProvider extends ChangeNotifier { final _db=DBHelper.instance; List<CartItem> _items=[]; List<CartItem> get items=>List.unmodifiable(_items); bool get isEmpty=>_items.isEmpty; int get totalQuantity=>_items.fold(0,(s,i)=>s+i.quantity); int get totalPrice=>_items.fold(0,(s,i)=>s+i.subtotal); CartProvider(){loadCart();} Future<void> loadCart() async {_items=(await _db.getCartItems()).map(CartItem.fromMap).toList();notifyListeners();} Future<void> addToCart(Product p) async {final ix=_items.indexWhere((i)=>i.product.id==p.id);if(ix>=0){await increment(p.id);return;}await _db.insertCart(p);await loadCart();} Future<void> increment(String id) async {final i=_items.where((x)=>x.product.id==id).firstOrNull;if(i==null)return;await _db.updateCartQuantity(id,i.quantity+1);await loadCart();} Future<void> decrement(String id) async {final i=_items.where((x)=>x.product.id==id).firstOrNull;if(i==null)return;if(i.quantity<=1){await removeItem(id);return;}await _db.updateCartQuantity(id,i.quantity-1);await loadCart();} Future<void> removeItem(String id) async {await _db.deleteCartItem(id);await loadCart();} Future<void> clearCart() async {for(final i in _items){await _db.deleteCartItem(i.product.id);}await loadCart();} }
